-- Paket ABT "abt-keputusan-a-kerangka-4nov" (4 Nov 2026): kerangka berisian + variabel baru (keputusan Derry 182/184). Hanya derry_briantono.
-- PRASYARAT "A|B|C": A = nomor 9266-9269 berisi lain dari paket (0) | B = variabel paket persis (0 pasang pertama / 4 pasang ulang) | C = yang dipakai ada: fungsi isian_rtf_ket_saksi, isian_rtf_terbilang dan variabel 6054, 6138, 8934, 1197 (6)
SELECT CONCAT_WS('|',
 (SELECT COUNT(*) FROM abt_variabel v WHERE v.no_var BETWEEN 9266 AND 9269 AND NOT EXISTS (SELECT 1 FROM (SELECT 9266 AS n, 'cdb271d6852c9cdc83f51454862c7652' AS h UNION ALL SELECT 9267 AS n, '6abb9f9c6efe62d469a428a099d48fe0' AS h UNION ALL SELECT 9268 AS n, 'be716591b6a903a93028bb123563275b' AS h UNION ALL SELECT 9269 AS n, '455d4eb01693fe52665111f213909f98' AS h) p WHERE p.n = v.no_var AND p.h = MD5(CONCAT_WS('|', v.nama, v.data_type, REPLACE(IFNULL(v.sql_query, ''), CONCAT(DATABASE(), '.'), 'aps_badilag.'), IFNULL(v.referensi, ''), IFNULL(v.multi_sidang, ''), v.locked, IFNULL(v.modifier, ''))))),
 (SELECT COUNT(*) FROM abt_variabel v JOIN (SELECT 9266 AS n, 'cdb271d6852c9cdc83f51454862c7652' AS h UNION ALL SELECT 9267 AS n, '6abb9f9c6efe62d469a428a099d48fe0' AS h UNION ALL SELECT 9268 AS n, 'be716591b6a903a93028bb123563275b' AS h UNION ALL SELECT 9269 AS n, '455d4eb01693fe52665111f213909f98' AS h) p ON p.n = v.no_var AND p.h = MD5(CONCAT_WS('|', v.nama, v.data_type, REPLACE(IFNULL(v.sql_query, ''), CONCAT(DATABASE(), '.'), 'aps_badilag.'), IFNULL(v.referensi, ''), IFNULL(v.multi_sidang, ''), v.locked, IFNULL(v.modifier, '')))),
 (SELECT (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema = DATABASE() AND routine_name IN ('isian_rtf_ket_saksi', 'isian_rtf_terbilang')) + (SELECT COUNT(*) FROM abt_variabel WHERE no_var IN (6054, 6138, 8934, 1197)))) AS p;
